#include "minecraft/WorldLoader.h"
#include "minecraft/Nbt.h"
#include <filesystem>
namespace sanbucraft::minecraft { namespace { const NbtTag* child(const NbtTag* tag, const char* key) { return tag ? tag->find(key) : nullptr; } }
bool WorldLoader::loadWorld(const std::string& path, WorldInfo& world, std::string& error) { namespace fs = std::filesystem; const fs::path directory = fs::weakly_canonical(path); if (!fs::is_directory(directory) || !fs::exists(directory / "level.dat")) { error = "Minecraft world must be a directory containing level.dat."; return false; } NbtTag root; if (!NbtReader::readFile((directory / "level.dat").string(), root, error)) return false; const NbtTag* data = root.find("Data"); if (!data || !data->compound()) { error = "level.dat does not contain a Data compound."; return false; } world = {}; world.path = directory.string(); world.name = child(data, "LevelName") ? child(data, "LevelName")->stringOr() : "Unnamed world"; world.gameTime = child(data, "Time") ? child(data, "Time")->integerOr() : 0; world.dataVersion = static_cast<int>(child(data, "DataVersion") ? child(data, "DataVersion")->integerOr() : 0); const NbtTag* worldGen = child(data, "WorldGenSettings"); world.seed = child(worldGen, "seed") ? child(worldGen, "seed")->integerOr() : 0; const NbtTag* version = child(data, "Version"); world.versionName = child(version, "Name") ? child(version, "Name")->stringOr() : "unknown"; if (const auto* rules = child(data, "GameRules"); rules && rules->compound()) for (const auto& [key, value] : *rules->compound()) world.gameRules[key] = value.stringOr(); return true; }
}
